const TREND_THRESHOLD = parseInt($env.TREND_THRESHOLD || '3');

const articles = Array.isArray(items[0].json) ? items[0].json : [];
const mentions  = Array.isArray(items[1]?.json) ? items[1].json : [];

// ── Company frequency from mentions table ────────────────────
const companyFreq = {};
for (const m of mentions) {
  const name = (m.company_name || '').toLowerCase();
  if (name) companyFreq[name] = (companyFreq[name] || 0) + 1;
}

// ── Deal type frequency ──────────────────────────────────────
const dealTypeFreq = {};
for (const art of articles) {
  const dt = art.deal_type || 'none';
  dealTypeFreq[dt] = (dealTypeFreq[dt] || 0) + 1;
}

// ── Geography frequency ──────────────────────────────────────
const geoFreq = {};
for (const art of articles) {
  const geo = art.geography || 'Unknown';
  geoFreq[geo] = (geoFreq[geo] || 0) + 1;
}

// ── Topic clustering by company ──────────────────────────────
const clusters = {};
for (const art of articles) {
  const companies = JSON.parse(art.companies || '[]');
  for (const co of companies) {
    const key = co.toLowerCase();
    if (!clusters[key]) clusters[key] = [];
    clusters[key].push(art.id);
  }
}

// ── Identify trending companies ──────────────────────────────
const trending = Object.entries(companyFreq)
  .filter(([, count]) => count >= TREND_THRESHOLD)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 20)
  .map(([name, count]) => ({ name, count }));

// ── Identify trending article IDs ────────────────────────────
const trendingCompanyNames = new Set(trending.map(t => t.name));
const trendingArticleIds = articles
  .filter(art => {
    const companies = JSON.parse(art.companies || '[]');
    return companies.some(co => trendingCompanyNames.has(co.toLowerCase()));
  })
  .map(art => art.id);

// ── Trend score per article ───────────────────────────────────
const trendScores = {};
for (const art of articles) {
  const companies = JSON.parse(art.companies || '[]');
  const score = companies.reduce((sum, co) => {
    return sum + (companyFreq[co.toLowerCase()] || 0);
  }, 0);
  trendScores[art.id] = score;
}

const topCompanies = Object.entries(companyFreq)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(([name, count]) => ({ name, count }));

const topDealTypes = Object.entries(dealTypeFreq)
  .sort((a, b) => b[1] - a[1])
  .map(([type, count]) => ({ type, count }));

const topGeographies = Object.entries(geoFreq)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(([geo, count]) => ({ geo, count }));

console.log(`Trend analysis: ${trending.length} trending companies, ${trendingArticleIds.length} trending articles`);

return [{
  json: {
    trending_article_ids: trendingArticleIds,
    trend_scores: trendScores,
    top_companies: topCompanies,
    top_deal_types: topDealTypes,
    top_geographies: topGeographies,
    total_articles: articles.length,
    trending_companies: trending,
  }
}];

const analysis = items[0].json;
const trendingIds = analysis.trending_article_ids || [];
const trendScores  = analysis.trend_scores || {};

// Build update records for each trending article
return trendingIds.map(id => ({
  json: {
    id,
    trending_flag: true,
    trend_score: trendScores[id] || 1,
    _analysis: analysis,
  }
}));

